export const VERSION = 1;
export const norm = value => String(value ?? '').normalize('NFKC').trim().toLocaleLowerCase();
export const key = r => [r.name,r.city,r.cuisine,r.address].map(norm).join('\u0000');
export function clean(input, defaults = {}) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) throw Error('Each restaurant must be an object.');
  const out = {};
  for (const field of ['name','city','cuisine','notes','address','url']) {
    const value = input[field] ?? defaults[field] ?? '';
    if (typeof value !== 'string') throw Error(`${field} must be text.`);
    if (value.length > (field === 'notes' ? 20000 : 1000)) throw Error(`${field} is too long.`);
    out[field] = value.trim();
  }
  if (!out.name || !out.city || !out.cuisine) throw Error('Name, city, and cuisine are required.');
  const stars=input.michelinStars??0;
  if(!['number','string'].includes(typeof stars)||! /^[0-3]$/.test(String(stars)))throw Error('Michelin stars must be 0, 1, 2, or 3.');
  out.michelinStars=Number(stars);
  const rating = input.rating;
  if (rating === '' || rating === null || rating === undefined) out.rating = null;
  else {
    if (!['number','string'].includes(typeof rating) || !/^\d+(\.\d+)?$/.test(String(rating).trim())) throw Error('Rating must be a number from 0 to 5, or blank.');
    out.rating = Number(rating);
    if (!Number.isFinite(out.rating) || out.rating < 0 || out.rating > 5) throw Error('Rating must be from 0 to 5.');
  }
  if (out.url) { let u; try {u = new URL(out.url);} catch {throw Error('Website must be a full http or https URL.');} if (!['http:','https:'].includes(u.protocol)) throw Error('Only http and https website links are allowed.'); out.url = u.href; }
  const tags = input.tags ?? [];
  if (!Array.isArray(tags) || tags.length > 50 || tags.some(t => typeof t !== 'string' || t.length > 100)) throw Error('Tags must be an array of short text values.');
  out.tags = [...new Set(tags.map(t=>t.trim()).filter(Boolean))];
  if (input.deletedAt != null && (typeof input.deletedAt !== 'string' || !Number.isFinite(Date.parse(input.deletedAt)))) throw Error('Invalid trash date.');
  out.deletedAt = input.deletedAt ?? null;
  return out;
}
export function sortRestaurants(rows, direction = 'best') {
  return [...rows].sort((a,b) => (a.rating == null) - (b.rating == null) || (a.rating != null && b.rating != null ? (direction === 'worst' ? a.rating-b.rating : b.rating-a.rating) : 0) || a.name.localeCompare(b.name,undefined,{sensitivity:'base'}));
}
export function parseCSV(text) {
  const rows=[]; let row=[],field='',quoted=false;
  for(let i=0;i<text.length;i++) { const c=text[i]; if(c==='"') {if(quoted&&text[i+1]==='"'){field+='"';i++;}else if(!quoted&&field.length){throw Error('Invalid CSV quoting.');}else quoted=!quoted;} else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field='';} else field+=c; }
  if(quoted)throw Error('CSV has an unfinished quote.'); row.push(field);if(row.some(v=>v.trim()))rows.push(row);return rows;
}
export function parseImport(text, defaults={}) {
  if(typeof text!=='string'||text.length>5_000_000)throw Error('Import must be text smaller than 5 MB.');
  const t=text.trim();if(!t)throw Error('Paste restaurants or choose a file first.'); let raw;
  if(t.startsWith('{')||t.startsWith('[')) {
    const data=JSON.parse(t);
    if(Array.isArray(data))raw=data;
    else {if(!['restaurant-log-backup','restaurant-log-import'].includes(data.format)||data.version!==VERSION||!Array.isArray(data.restaurants))throw Error('Unsupported JSON format or version.');raw=data.restaurants;}
  } else {
    const rows=parseCSV(t);const headers=rows[0].map(norm);const allowed=['name','city','cuisine','rating','notes','address','url','tags','michelinstars'];
    if(headers.includes('name')) {if(headers.some(h=>!allowed.includes(h))||new Set(headers).size!==headers.length)throw Error('CSV headers must be unique: name, city, cuisine, rating, notes, address, url, tags, michelinStars.');raw=rows.slice(1).map(row=>{if(row.length>headers.length)throw Error('CSV row has more values than its header.');const obj=Object.fromEntries(headers.map((h,i)=>[h,row[i]??'']));if(obj.michelinstars!==undefined){obj.michelinStars=obj.michelinstars||0;delete obj.michelinstars;}if(obj.tags!==undefined)obj.tags=obj.tags.split(';').map(t=>t.trim()).filter(Boolean);return obj;});}
    else raw=t.split(/\r?\n/).map(name=>({name:name.trim()})).filter(r=>r.name);
  }
  if(raw.length>2000)throw Error('Import at most 2,000 restaurants at a time.');
  return raw.map((r,i)=>{try{return {value:clean(r,defaults),error:null};}catch(e){return {value: r&&typeof r==='object'&&!Array.isArray(r)?{...r}: {name:''},error:`Row ${i+1}: ${e.message}`};}});
}
export function planImport(existing, incoming) {
  const ids=new Set(existing.map(key));const add=[];let duplicates=0;
  for(const row of incoming){const r=clean(row);const k=key(r);if(ids.has(k)){duplicates++;continue;}ids.add(k);add.push(r);}return {add,duplicates};
}


export function sortMichelin(rows){return sortRestaurants(rows.filter(r=>!r.deletedAt&&r.michelinStars>0)).sort((a,b)=>b.michelinStars-a.michelinStars);}

// Display explicit tasting scores; keep the source notes intact and never average them.
export function tastingNotes(notes){
 const lines=String(notes??'').split(/\r?\n/),items=[],general=[];
 for(const line of lines){
  const match=line.match(/^(.*?)\s*(\d+(?:\.\d+)?)\s*(?:\/\s*a?5|:\s*5)\b(.*)$/i);
  if(!match||Number(match[2])>5||!match[1].trim()){if(line.trim())general.push(line.trim());continue;}
  const name=match[1].trim().replace(/[—–:\s]+$/,'').trim(),comment=match[3].trim().replace(/^[.,;\s]+/,'');
  items.push({name,rating:Number(match[2]),comment});
 }
 return {items,general};
}

const GITHUB_ROOT='https://raw.githubusercontent.com/asre1212/Restuarants/main/inbox';
const GITHUB_HEADERS={'Accept':'application/vnd.github+json','User-Agent':'Restaurants-inbox'};
const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const to64=b=>btoa(Array.from(new Uint8Array(b),v=>String.fromCharCode(v)).join(''));
async function digestHex(text){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),b=>b.toString(16).padStart(2,'0')).join('');}
async function recipientFor(request){const email=request.headers.get('oai-authenticated-user-email');if(!email||!request.headers.get('oai-authenticated-user-id'))throw Error('Connect the same ChatGPT account used to send the list.');return digestHex(email.trim().toLowerCase());}
async function encryptionKey(env){if(!env.GITHUB_INBOX_KEY)throw Error('GitHub inbox encryption is not configured.');return crypto.subtle.importKey('raw',from64(env.GITHUB_INBOX_KEY),'AES-GCM',false,['encrypt','decrypt']);}
const envelopeAAD=e=>new TextEncoder().encode(JSON.stringify([e.id,e.recipient,e.expiresAt]));
async function receiptToken(env,id,recipient,receipt){const key=await crypto.subtle.importKey('raw',from64(env.GITHUB_INBOX_KEY),{name:'HMAC',hash:'SHA-256'},false,['sign']);return to64(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(JSON.stringify([id,recipient,receipt]))));}
async function decodeEnvelope(request,env,e){
 if(e?.format!=='restaurants-encrypted-inbox'||e.version!==1||!/^[A-Za-z0-9_-]{8,100}$/.test(e.id||'')||typeof e.ciphertext!=='string'||e.ciphertext.length>700000||typeof e.iv!=='string'||!Number.isFinite(e.expiresAt))throw Error('Invalid GitHub delivery.');
 if(e.recipient!==await recipientFor(request))return null;
 if(e.expiresAt<=Date.now())throw Error('GitHub delivery expired. Ask your assistant to resend it.');
 const clear=await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(e.iv),additionalData:envelopeAAD(e)},await encryptionKey(env),from64(e.ciphertext));
 const packet=JSON.parse(new TextDecoder().decode(clear));const parsed=parseImport(JSON.stringify(packet));if(parsed.some(r=>r.error))throw Error('GitHub delivery has invalid restaurant fields.');
 const receipt=await digestHex(e.ciphertext);return {id:e.id,packet,receipt,receiptToken:await receiptToken(env,e.id,e.recipient,receipt)};
}
export async function prepareGitHubDelivery(request,env,args){
 if(!/^[A-Za-z0-9_-]{8,100}$/.test(args.delivery_id||''))throw Error('Provide a stable delivery_id of 8–100 characters.');
 if(!Array.isArray(args.restaurants)||!args.restaurants.length||args.restaurants.length>100)throw Error('Send 1–100 restaurants.');
 const packet={format:'restaurant-log-import',version:1,restaurants:args.restaurants.map(r=>clean(r))};
 const e={format:'restaurants-encrypted-inbox',version:1,id:args.delivery_id,recipient:await recipientFor(request),expiresAt:Date.now()+7*86400000,iv:to64(crypto.getRandomValues(new Uint8Array(12)))};
 e.ciphertext=to64(await crypto.subtle.encrypt({name:'AES-GCM',iv:from64(e.iv),additionalData:envelopeAAD(e)},await encryptionKey(env),new TextEncoder().encode(JSON.stringify(packet))));
 return {prepared:packet.restaurants.length,github_path:`inbox/${e.id}.json`,github_payload:e,saved_on_device:false,next_step:'Save github_payload to github_path in asre1212/Restuarants on main using GitHub, and add that filename to inbox/index.json (format restaurants-inbox-index, version 1, files array). Only then confirm it is queued. The user presses Force pull list to save it locally and acknowledge deletion.'};
}
async function githubJSON(url){const r=await fetch(url,{headers:GITHUB_HEADERS,cache:'no-store'});if(r.status===404)return null;if(!r.ok)throw Error(`GitHub returned ${r.status}. Try again later.`);const text=await r.text();if(text.length>1000000)throw Error('GitHub response too large.');return JSON.parse(text);}
export async function githubInboxFetch(request,env){
 const url=new URL(request.url);
 const receiptMatch=url.pathname.match(/^\/api\/github\/receipt\/([a-f0-9]{64})$/);
 // Public non-sensitive receipt status allows the GitHub cleanup workflow to verify acknowledgement.
 if(receiptMatch&&request.method==='GET'){const record=await env.BUCKET?.get('github-receipt/'+receiptMatch[1]);return json({acknowledged:!!record});}
 if(request.method!=='POST')return json({error:'POST required.'},405);
 if(request.headers.get('Origin')!==url.origin)return json({error:'Same-origin request required.'},403);
 try{
  const recipient=await recipientFor(request);
  if(url.pathname==='/api/github/pull'){
   const listing=await githubJSON(GITHUB_ROOT+'/index.json?fresh='+Date.now());if(!listing)return json({packets:[],message:'No GitHub deliveries waiting.'});
   if(listing.format!=='restaurants-inbox-index'||listing.version!==1||!Array.isArray(listing.files))throw Error('Invalid GitHub inbox index.');
   const files=listing.files;if(files.some(f=>typeof f!=='string'||! /^[A-Za-z0-9_-]{8,100}\.json$/.test(f)))throw Error('Invalid GitHub inbox filename.');if(files.length>20)throw Error('More than 20 GitHub deliveries. Ask your assistant to split the queue.');
   const packets=[];
   for(const file of files){const e=await githubJSON(GITHUB_ROOT+'/'+encodeURIComponent(file)+'?fresh='+Date.now());if(!e)continue;if(file!==e.id+'.json')throw Error('GitHub delivery ID does not match its filename.');const packet=await decodeEnvelope(request,env,e);if(packet)packets.push(packet);}
   return json({packets,unmatched:files.length>0&&packets.length===0});
  }
  if(url.pathname==='/api/github/ack'){
   if(!env.BUCKET)throw Error('Receipt storage unavailable.');
   const body=await readJSON(request);if(!/^[A-Za-z0-9_-]{8,100}$/.test(body.id||'')||!/^[a-f0-9]{64}$/.test(body.receipt||''))throw Error('Invalid acknowledgement.');
   const expected=await receiptToken(env,body.id,recipient,body.receipt);if(body.receiptToken!==expected)throw Error('Acknowledgement is not authorized for this account.');
   await env.BUCKET.put('github-receipt/'+body.receipt,JSON.stringify({id:body.id,acknowledgedAt:Date.now()}));
   if(!await env.BUCKET.get('github-receipt/'+body.receipt))throw Error('Could not verify acknowledgement storage. The GitHub file has been kept.');
   return json({acknowledged:true,github_cleanup:'scheduled'});
  }
  return json({error:'Not found.'},404);
 }catch(e){return json({error:e.message},e.message.startsWith('Connect')?401:400);}
}

// Server holds delivery packets only. It never receives the device notebook.
const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','Vary':'Cookie'}});
const fieldSchema={type:'object',additionalProperties:false,required:['name','city','cuisine'],properties:{michelinStars:{type:'integer',minimum:0,maximum:3},name:{type:'string'},city:{type:'string'},cuisine:{type:'string'},rating:{type:['number','null'],minimum:0,maximum:5},notes:{type:'string'},address:{type:'string'},url:{type:'string'},tags:{type:'array',items:{type:'string'}}}};
const tools=[
 {name:'add_restaurants',description:'Prepare an encrypted GitHub delivery. Save the returned github_payload at github_path in asre1212/Restuarants on main using GitHub and add its filename to inbox/index.json. Only then confirm it is queued. The user presses Force pull list to save entries locally and acknowledge GitHub deletion. Cannot read, modify, or sync existing notebook data. Never infer personal ratings. Use a stable delivery_id to retry the same packet.',inputSchema:{type:'object',additionalProperties:false,required:['restaurants','delivery_id'],properties:{restaurants:{type:'array',minItems:1,maxItems:100,items:fieldSchema},delivery_id:{type:'string',pattern:'^[A-Za-z0-9_-]{8,100}$'}}}},
 {name:'restaurant_inbox_status',description:'Return pending delivery count for the caller, without reading their device notebook.',inputSchema:{type:'object',additionalProperties:false,properties:{}}}
];
async function prefixFor(user){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(user));return 'inbox/'+Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('')+'/';}
async function readPackets(bucket,prefix){const listing=await bucket.list({prefix,limit:100});const packets=[];for(const item of listing.objects){const object=await bucket.get(item.key);if(!object)continue;const packet=await object.json();if(packet.expiresAt<=Date.now()){await bucket.delete(item.key);continue;}packets.push(packet);}return packets.sort((a,b)=>a.createdAt-b.createdAt);}
async function readJSON(request){const text=await request.text();if(text.length>500000)throw Error('Request too large.');return JSON.parse(text);}
export async function inboxFetch(request,env){
 const url=new URL(request.url),user=request.headers.get('oai-authenticated-user-id');
 if(url.pathname.startsWith('/api/github/'))return githubInboxFetch(request,env);
 if(url.pathname==='/mcp'){
  if(request.method!=='POST')return json({error:'POST required'},405);
  let msg;try{msg=await readJSON(request);}catch(e){return json({error:e.message},400);}
  if(msg.id==null)return new Response(null,{status:202});
  const reply=result=>json({jsonrpc:'2.0',id:msg.id,result});
  if(msg.method==='server/discover')return reply({supportedVersions:['2026-07-28'],capabilities:{tools:{}}});
  if(msg.method==='initialize')return reply({protocolVersion:msg.params?.protocolVersion||'2026-07-28',capabilities:{tools:{}},serverInfo:{name:'table-notes',version:'2.0.0'}});
  if(msg.method==='tools/list')return reply({tools});
  if(msg.method==='ping')return reply({});
  if(msg.method!=='tools/call')return json({jsonrpc:'2.0',id:msg.id,error:{code:-32601,message:'Method not found'}});
  try{
   if(!user)throw Error('Connect your ChatGPT account to use the inbox.');
   if(!env.BUCKET)throw Error('Inbox storage unavailable.');
   const prefix=await prefixFor(user),name=msg.params?.name,args=msg.params?.arguments||{};
   let result;
   if(name==='restaurant_inbox_status'){const pending=await readPackets(env.BUCKET,prefix);result={pending_deliveries:pending.length,pending_restaurants:pending.reduce((n,p)=>n+p.packet.restaurants.length,0),device_notebook_access:false};}
   else if(name==='add_restaurants'){
    if(env.GITHUB_INBOX_KEY)return reply({content:[{type:'text',text:JSON.stringify(await prepareGitHubDelivery(request,env,args))}]});
    if(!/^[A-Za-z0-9_-]{8,100}$/.test(args.delivery_id||''))throw Error('Provide a stable delivery_id of 8–100 letters, numbers, underscores or hyphens.');
    if(!Array.isArray(args.restaurants)||args.restaurants.length<1||args.restaurants.length>100)throw Error('Send 1–100 restaurants at a time.');
    const restaurants=args.restaurants.map(r=>{const value=clean(r);if(value.deletedAt)throw Error('New deliveries cannot be in Trash.');return value;});
    const existing=await env.BUCKET.get(prefix+args.delivery_id);
    if(existing){const prior=await existing.json();if(JSON.stringify(prior.packet.restaurants)!==JSON.stringify(restaurants))throw Error('delivery_id already belongs to a different packet.');result={queued:restaurants.length,delivery_id:args.delivery_id,already_pending:true};}
    else{const pending=await readPackets(env.BUCKET,prefix);if(pending.length>=20)throw Error('Inbox has 20 deliveries. Open the app to save them first.');const now=Date.now();await env.BUCKET.put(prefix+args.delivery_id,JSON.stringify({id:args.delivery_id,createdAt:now,expiresAt:now+7*86400000,packet:{format:'restaurant-log-import',version:1,restaurants}}),{httpMetadata:{contentType:'application/json'}});result={queued:restaurants.length,delivery_id:args.delivery_id};}
    result.saved_on_device=false;result.next_step='Open Restaurants signed in with this ChatGPT account. The first device to import saves the entries locally and removes the delivery.';
   }else throw Error('Unknown tool.');
   return reply({content:[{type:'text',text:JSON.stringify(result)}]});
  }catch(e){return reply({isError:true,content:[{type:'text',text:e.message}]});}
 }
 if(url.pathname.startsWith('/api/inbox')){
  if(!user)return json({error:'Sign in with ChatGPT to connect your inbox.'},401);
  if(!env.BUCKET)return json({error:'Inbox storage unavailable.'},503);
  try{const prefix=await prefixFor(user);
   if(url.pathname==='/api/inbox'&&request.method==='GET')return json({packets:await readPackets(env.BUCKET,prefix)});
   if(url.pathname==='/api/inbox/ack'&&request.method==='POST'){
    if(request.headers.get('Origin')!==url.origin)return json({error:'Same-origin request required.'},403);
    const body=await readJSON(request);if(!Array.isArray(body.ids)||body.ids.length>20||body.ids.some(id=>typeof id!=='string'||!/^[A-Za-z0-9_-]{8,100}$/.test(id)))return json({error:'Invalid receipt IDs.'},400);
    for(const id of body.ids)await env.BUCKET.delete(prefix+id);return json({removed:body.ids.length});
   }return json({error:'Not found'},404);
  }catch(e){return json({error:e.message},400);}
 }
 return null;
}

const assets={"/index.html":{"type":"text/html","bytes":""},"/app.js":{"type":"text/javascript","bytes":""},"/sw.js":{"type":"text/javascript","bytes":""},"/core.js":{"type":"text/javascript","bytes":""},"/db.js":{"type":"text/javascript","bytes":""},"/style.css":{"type":"text/css","bytes":""},"/manifest.webmanifest":{"type":"application/manifest+json","bytes":""},"/icons/icon.svg":{"type":"image/svg+xml","bytes":""},"/icons/icon-192.png":{"type":"image/png","bytes":""},"/icons/icon-512.png":{"type":"image/png","bytes":""},"/icons/apple-touch-icon.png":{"type":"image/png","bytes":""}};
export default {async fetch(request,env){const response=await inboxFetch(request,env);if(response)return response;let path=new URL(request.url).pathname;if(path==='/')path='/index.html';const asset=assets[path];if(!asset||!['GET','HEAD'].includes(request.method))return new Response('Not found',{status:404});const headers={'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'};return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(asset.bytes),c=>c.charCodeAt(0)),{headers});}};
